  const r=d.related, events=[...r.inquiries,...r.communications,...r.tasks.map(t=>({...t,channel:'跟进任务 · '+t.status,summary:t.title,occurred_at:t.completed_at || t.updated_at})),...r.opportunities.map(o=>({...o,channel:'销售机会 · '+o.stage,summary:o.name,occurred_at:o.updated_at})),...(d.user?[{channel:'账户注册',summary:'邮箱验证成功',occurred_at:d.user.registered_at}]:[])];
