async function importContacts(){
 modal('导入客户',`<p class="small">UTF-8 CSV，最多 5,000 行。下一步可映射中文或英文表头，不覆盖已有记录。</p><label class="field">选择 CSV 文件<input name="file" type="file" accept=".csv,text/csv" required></label>`,async(_form,el)=>{
  const file=$('input[type=file]',el).files[0];if(file.size>2000000)throw new Error('文件不得超过 2 MB');
  const csv=await file.text();const result=await post('import/headers',{csv});
  setTimeout(()=>modal('映射客户字段',`<p class="small">请选择每个客户字段对应的 CSV 列。姓名必选，邮箱或电话至少选一项。</p><div class="form-grid">${[['name','姓名'],['email','邮箱'],['phone','电话'],['company','公司'],['tags','标签']].map(([key,label])=>field(key,label,'select',result.headers.includes(key)?key:result.headers.includes(label)?label:'',key==='name',result.headers)).join('')}</div>`,async mapping=>{
   const preview=await post('import/preview',{csv,mapping});
   setTimeout(()=>modal('确认导入客户',`<p>共 ${preview.total} 行，可导入 ${preview.valid} 行，跳过 ${preview.errors.length} 行。</p>${preview.errors.length?`<div class="notice">${preview.errors.slice(0,20).map(e=>`第 ${e.line} 行：${esc(e.error)}`).join('<br>')}</div>`:''}`,async()=>{const r=await post('import/commit',{id:preview.id});toast(`导入完成：新增 ${r.created}，跳过 ${r.skipped}，失败 ${r.failed.length}`);if(r.failed.length)setTimeout(()=>modal('导入结果',`<p>${r.failed.map(e=>`第 ${e.line} 行：${esc(e.error)}`).join('<br>')}</p>`,async()=>{},'关闭'),0);},'确认导入'),0);
  },'校验并预览'),0);
 },'读取文件');
}
