async function boot(){
 try{
  config=await api('config');
  if(location.pathname==='/notify'){const token=location.hash.startsWith('#verify=')?location.hash.slice(8):'';history.replaceState(null,'','/notify');const result=await post('notify/verify',{token});$('#app').innerHTML=`<main id="main" class="auth-form">${brand}<h2>通知邮箱验证</h2><p class="notice">${esc(result.message)}</p><a class="link" href="/admin#settings">返回系统设置 ↗</a></main>`;return;}
  if(location.pathname==='/inquiry' || location.pathname==='/register'){await publicPage();return;}
  try{session=await api('session');}catch{session=null;}
  if(session?.role==='admin')await render();
  else if(session?.role==='user')$('#app').innerHTML=`<main class="auth-form" id="main">${brand}<h2>当前为客户账户</h2><p>此账户没有管理后台权限。</p><button data-logout>退出并返回管理员登录</button></main>`;
  else await loginPage();
 }catch(error){$('#app').innerHTML=`<main class="auth-form" id="main"><p class="error">${esc(error.message)}</p><button data-refresh>重试</button></main>`;}
}
